import{_ as e,o,c as n,ah as r}from"./chunks/framework.BTzSx-Rb.js";const s="data:image/png;base64,",a="/projects/JetTank/en/latest/assets/image2.BZo085aF.webp",b=JSON.parse('{"title":"16.1 FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"docs/16.1 FAQ.md","filePath":"docs/16.1 FAQ.md"}'),i={name:"docs/16.1 FAQ.md"};function c(l,t,h,p,g,d){return o(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="_16-1-faq" tabindex="-1">16.1 FAQ <a class="header-anchor" href="#_16-1-faq" aria-label="Permalink to &quot;16.1 FAQ&quot;">​</a></h1><h2 id="_16-1-1-faq" tabindex="-1">16.1.1 FAQ <a class="header-anchor" href="#_16-1-1-faq" aria-label="Permalink to &quot;16.1.1 FAQ&quot;">​</a></h2><p><strong>Q1:</strong> Why does the robot not work after turning on power switch?</p><p><strong>A1:</strong> Check whether battery wire is connected. For shipping safety, battery wire is disconnected. Before charging and operating robot, you need to connect battery wire following the instructions in “<strong>1. Basic Lesson -&gt; Lesson 2 Device Charging</strong>”.</p><p><strong>Q2:</strong> Why can Android app connect to robot Wi-Fi, but cannot search for the robot?</p><p><strong>A2:</strong> 1. Check whether all necessary permissions are granted to the app.</p><p>2. Ensure mobile data is turned off, and location service is turned on.</p><p>3. Reconnect to the device WiFi, then return to app. Tap <img loading="lazy" height="26" width="27" src="'+s+'"> to refresh.</p><p><strong>Q3:</strong> Why can’t 7-inch LCD screen support touch control?</p><p><strong>A3:</strong> Check whether the power cable of screen is connected to “CTOUCH” port. Only when it is connected to “CTOUCH” port, screen supports touch control.</p><p><strong>Q4:</strong> Why there is no live camera feed on the app?</p><p><strong>A4:</strong> Accidental touching while operating the robot may cause the camera cable to become loose, resulting in no live camera feed on the app. Please ensure that the camera cable is securely connected or try re-plugging it before using the robot.</p><p><strong>Q5:</strong> Why does the buzzer on the robot emit a &quot;beep&quot; sound after the robot has been working for a while?</p><p><strong>A5:</strong> The robot has low-voltage alarm. When the voltage drops below 10V, its buzzer will emit a “beep” to remind you of charging the robot.</p><p><strong>Q6:</strong> Why the robot might not perform well in object tracking or line following tasks?</p><ul><li><strong>A6</strong></li></ul><p>1. The size of the color picking circle should be set appropriately. If it is too large, it may mistakenly select the color of objects other than the target. Conversely, if it is too small, it may not capture the color of the target accurately.</p><p>2. It is important to ensure that there are no objects with colors similar to the target object around.</p><p>3. When experiencing the object tracking game, it is recommended to move the object on the ground to allow the robot to track it more effectively.</p><p><strong>Q7:</strong> Why can&#39;t we control the robot through the app or wireless handle?</p><p><strong>A7:</strong> Please confirm that the installation and connectivity of app are correct and that the handle receiver is properly inserted into the robot. Additionally, you will need to enable the app auto-start service by referring to the PDF file provided in “<strong>7. Motion Control Lesson-&gt;1. Basic Control Lesson-&gt;Lesson 9 Handle Control</strong>”. This service includes the handle control function, so it is important to ensure that it is properly enabled.</p><p><span class="mark"><strong>Q8:</strong> How can we resolve the issue of the computer being unable to detect the robot&#39;s hotspot after disabling &quot;Enable Wi-Fi&quot; on the robot&#39;s system desktop?</span></p><ul><li><strong>A8</strong></li></ul><p>1. Connect Jetson Nano and computer through USB cable.</p><p>2. Access the robot system desktop using the fixed IP by following the instructions accessible in “<strong>7. Motion Control Lesson-&gt;1. Basic Control Lesson-&gt;Lesson 1 Set Development Environment</strong>”.</p><p>3. Refresh the Wi-Fi list on both your phone and computer to check whether the robot’s Wi-Fi is available.</p><img loading="lazy" height="333" width="836" src="'+a+'" class="common_img" style="width:800px;"><p><strong>Q9:</strong> How can we enable the robot to connect to the external internet?</p><p><strong>A9:</strong> To allow the robot to access the external internet, you will need to configure the robot to STA LAN mode. Please refer to “<strong>1. Basic Lesson-&gt;Lesson 6 App Connection</strong>” for detailed instruction.</p>',29)])])}const A=e(i,[["render",c]]);export{b as __pageData,A as default};
